import sys

data = sys.stdin.read().split()
n = int(data[0])
best = -1
for name in data[1:1 + n]:
    ok = name.startswith('File_') and len(name) > 5
    for c in name[5:]:
        if c not in '0123456789':
            ok = False
    if ok:
        v = 0
        for c in name[5:]:
            v = v * 10 + int(c)
        if v > best:
            best = v
print(best)

